def _packet_section_mode(line: str, current_mode: str) -> str:
    lower = line.lower()
    if "[hard" in lower or "hard constraints" in lower:
        return "HARD"
    if "[soft" in lower or "soft constraints" in lower:
        return "SOFT"
    if "verification procedures" in lower or "limitations" in lower:
        return "SOFT"
    return current_mode


def _split_packet_units(text: str) -> list[dict[str, str]]:
    """Split a packet into headers and individual directives."""
    import re

    units: list[dict[str, str]] = []
    current_mode = "SOFT"
    current_item: dict[str, str] | None = None

    def flush_item() -> None:
        nonlocal current_item
        if current_item and current_item["text"].strip():
            current_item["text"] = re.sub(r"\s+", " ", current_item["text"]).strip()
            units.append(current_item)
        current_item = None

    for raw_line in text.splitlines():
        stripped = raw_line.strip()
        if not stripped:
            flush_item()
            continue

        next_mode = _packet_section_mode(stripped, current_mode)
        is_header = (
            stripped.startswith("[")
            or stripped.startswith("===")
            or stripped.startswith("#")
        )
        is_item_start = bool(re.match(r"^(\d+[.)]|[-*])\s+", stripped))

        if is_header:
            flush_item()
            current_mode = next_mode
            units.append(
                {"kind": "header", "text": stripped, "constraint_class": current_mode}
            )
            continue

        if next_mode != current_mode:
            flush_item()
            current_mode = next_mode

        if is_item_start:
            flush_item()
            current_item = {
                "kind": "item",
                "text": stripped,
                "constraint_class": current_mode,
            }
            continue

        if current_item is None:
            current_item = {
                "kind": "item",
                "text": stripped,
                "constraint_class": current_mode,
            }
        else:
            current_item["text"] += f" {stripped}"

    flush_item()
    return units


def _drop_orphan_headers(units: list[dict[str, str]]) -> list[dict[str, str]]:
    """Remove section headers that no longer contain any items."""
    cleaned: list[dict[str, str]] = []
    for index, unit in enumerate(units):
        if unit["kind"] != "header":
            cleaned.append(unit)
            continue
        has_item = False
        cursor = index + 1
        while cursor < len(units) and units[cursor]["kind"] != "header":
            if units[cursor]["kind"] == "item":
                has_item = True
                break
            cursor += 1
        if has_item:
            cleaned.append(unit)
    return cleaned


def _reassemble_packet_units(units: list[dict[str, str]]) -> str:
    lines: list[str] = []
    for unit in units:
        if unit["kind"] == "header" and lines:
            lines.append("")
        lines.append(unit["text"])
    return "\n".join(lines).strip()


def _intra_packet_prune(packet: DirectivePacket, char_budget: int) -> DirectivePacket:
    """Prune individual SOFT directives inside a packet before dropping the packet."""
    if len(packet.text) <= char_budget:
        return packet
    if packet.constraint_class == "HARD":
        return packet

    units = _split_packet_units(packet.text)
    keep = set(range(len(units)))
    soft_item_indices = [
        index
        for index, unit in enumerate(units)
        if unit["kind"] == "item" and unit["constraint_class"] != "HARD"
    ]

    def render_current() -> str:
        remaining = [units[i] for i in range(len(units)) if i in keep]
        remaining = _drop_orphan_headers(remaining)
        return _reassemble_packet_units(remaining)

    current_text = render_current()
    if len(current_text) <= char_budget:
        return DirectivePacket(
            layer=packet.layer,
            name=packet.name,
            text=current_text,
            constraint_class=packet.constraint_class,
            domain=packet.domain,
            model=packet.model,
            tags=set(packet.tags),
        )

    for index in reversed(soft_item_indices):
        keep.discard(index)
        current_text = render_current()
        if len(current_text) <= char_budget:
            break

    return DirectivePacket(
        layer=packet.layer,
        name=packet.name,
        text=current_text,
        constraint_class=packet.constraint_class,
        domain=packet.domain,
        model=packet.model,
        tags=set(packet.tags) | {"intra_pruned"},
    )
