def _apply_phenotype_transform(text: str, transform: PhenotypeTransform) -> str:
    """Apply stronger phenotype rendering for constrained models."""
    import re

    STOPWORDS = {
        "a", "an", "and", "as", "at", "be", "by", "for", "from", "if", "in",
        "into", "is", "it", "of", "on", "or", "that", "the", "to", "use",
        "with", "without",
    }
    SYNONYMS = {
        "brief": "concise",
        "minimal": "concise",
        "short": "concise",
        "simple": "concise",
        "simpler": "concise",
        "detailed": "detailed",
        "detail": "detailed",
        "proofs": "proof",
        "proof": "proof",
        "examples": "example",
        "rationales": "rationale",
        "reasons": "rationale",
        "tables": "table",
        "tabular": "table",
    }

    def normalise_tokens(value: str) -> set[str]:
        lowered = value.lower()
        lowered = re.sub(r"`([^`]*)`", r"\1", lowered)
        lowered = re.sub(r"[*_~]+", " ", lowered)
        tokens = set()
        for token in re.findall(r"[a-z0-9]+", lowered):
            token = SYNONYMS.get(token, token)
            if token not in STOPWORDS:
                tokens.add(token)
        return tokens

    def semantically_duplicate(left: str, right: str) -> bool:
        left_tokens = normalise_tokens(left)
        right_tokens = normalise_tokens(right)
        if not left_tokens or not right_tokens:
            return False
        if left_tokens == right_tokens:
            return True
        overlap = len(left_tokens & right_tokens) / len(left_tokens | right_tokens)
        return overlap >= 0.85

    def starts_new_block(line: str) -> bool:
        return bool(
            re.match(r"^(\d+[.)]|[-*])\s+", line)
            or line.endswith(":")
            or line.startswith("[")
            or line.startswith("===")
        )

    text = text.replace("\r\n", "\n").replace("\r", "\n").strip()
    if not text:
        return text

    filtered_lines: list[str] = []
    skipping_examples = False

    for raw_line in text.split("\n"):
        stripped = raw_line.strip()

        if transform.strip_examples and re.match(r"(?i)^(example|examples|e\.g\.)\s*:", stripped):
            skipping_examples = True
            continue
        if skipping_examples and (
            not stripped
            or re.match(r"^(#{1,6}\s+|\[[^\]]+\]|===|---)", stripped)
        ):
            skipping_examples = False
        if skipping_examples:
            continue

        if transform.strip_rationale and re.match(
            r"(?i)^(why|rationale|motivation|reason)\s*:", stripped
        ):
            continue

        if transform.compress_tables and stripped.startswith("|"):
            cells = [cell.strip() for cell in stripped.split("|") if cell.strip()]
            is_separator = cells and all(set(cell) <= {"-"} for cell in cells)
            if cells and not is_separator:
                filtered_lines.append(", ".join(cells))
            continue

        header_match = re.match(r"^#{1,6}\s+(.*)$", stripped)
        if header_match:
            label = header_match.group(1).strip().strip(":")
            if label:
                filtered_lines.append(f"{label}:")
            continue

        if stripped:
            filtered_lines.append(stripped)

    blocks: list[list[str]] = []
    current: list[str] = []

    for line in filtered_lines:
        if starts_new_block(line):
            if current:
                blocks.append(current)
            current = [line]
        else:
            if not current:
                current = [line]
            else:
                current.append(line)
    if current:
        blocks.append(current)

    collapsed: list[str] = []
    for block in blocks:
        head = block[0]
        tail = block[1:]
        if re.match(r"^(\d+[.)]|[-*])\s+", head):
            prefix, _, rest = head.partition(" ")
            payload = " ".join([rest] + tail).strip()
            payload = re.sub(r"\s+", " ", payload)
            collapsed.append(f"{prefix} {payload}".strip())
        elif head.endswith(":") and not tail:
            collapsed.append(head)
        else:
            payload = " ".join(block)
            payload = re.sub(r"\s+", " ", payload).strip()
            if transform.simplify_language:
                payload = payload.replace("must not", "do not")
                payload = payload.replace("should not", "avoid")
                payload = payload.replace("is required to", "must")
            collapsed.append(payload)

    deduped: list[str] = []
    for block in collapsed:
        if not any(semantically_duplicate(block, existing) for existing in deduped):
            deduped.append(block)

    rendered_blocks: list[str] = []
    for block in deduped:
        candidate = "\n".join(rendered_blocks + [block]).strip()
        if len(candidate) > transform.max_directive_chars:
            break
        rendered_blocks.append(block)

    return "\n".join(rendered_blocks).strip()
