@dataclass(frozen=True)
class ConflictRecord:
    topic: str
    winner_layer: str
    winner_packet: str
    winner_text: str
    loser_layer: str
    loser_packet: str
    loser_text: str
    reason: str


def _build_phenotype_packet_from_manifest(manifest: dict[str, Any]) -> DirectivePacket | None:
    transform = manifest.get("phenotype_transform", {})
    directives: list[str] = []

    format_style = transform.get("format_style")
    if format_style == "minimal":
        directives.append("Use minimal format.")
    elif format_style == "concise":
        directives.append("Use concise format.")

    if transform.get("simplify_language"):
        directives.append("Use simple language.")
    if transform.get("strip_examples"):
        directives.append("Do not include examples unless required.")
    if transform.get("strip_rationale"):
        directives.append("Do not include rationale unless required.")
    if transform.get("compress_tables"):
        directives.append("Prefer inline text over tables.")

    if not directives:
        return None

    return DirectivePacket(
        layer="phenotype",
        name=f"phenotype_{manifest.get('model', 'unknown')}",
        text="\n".join(directives),
        constraint_class="SOFT",
        model=manifest.get("model"),
        tags={"phenotype"},
    )


def _split_conflict_directives(text: str) -> list[str]:
    import re

    directives: list[str] = []
    current: list[str] = []
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            if current:
                directives.append(" ".join(current))
                current = []
            continue
        if re.match(r"^(\d+[.)]|[-*])\s+", line) or line.endswith(":"):
            if current:
                directives.append(" ".join(current))
            current = [line]
        else:
            if not current:
                current = [line]
            else:
                current.append(line)
    if current:
        directives.append(" ".join(current))
    return [re.sub(r"\s+", " ", directive).strip() for directive in directives if directive.strip()]


def _directive_topic_and_stance(text: str) -> tuple[str | None, str | None]:
    lower = text.lower()

    if any(word in lower for word in ("minimal", "concise", "brief", "simple format")):
        return "verbosity", "low"
    if any(word in lower for word in ("detailed", "exhaustive", "full proof", "formal proof")):
        return "verbosity", "high"

    if "example" in lower:
        if any(word in lower for word in ("do not", "avoid", "strip", "remove", "without")):
            return "examples", "exclude"
        return "examples", "include"

    if any(word in lower for word in ("rationale", "reason", "motivation", "why")):
        if any(word in lower for word in ("do not", "avoid", "strip", "remove", "without")):
            return "rationale", "exclude"
        return "rationale", "include"

    if "table" in lower or "tabular" in lower:
        if any(word in lower for word in ("inline", "plain text", "compress", "without")):
            return "table", "exclude"
        return "table", "include"

    return None, None


def _layer_priority(layer: str) -> int:
    return {
        "universal": 4,
        "domain": 3,
        "phenotype": 2,
        "situation": 1,
    }.get(layer, 0)


def _specificity_score(packet: DirectivePacket) -> int:
    score = 0
    if packet.domain:
        score += 2
    if packet.layer == "situation":
        score += 1
    if "_" in packet.name:
        score += 1
    return score


def resolve_layer_conflicts(
    composed: ComposedDirectiveSet,
) -> tuple[ComposedDirectiveSet, list[ConflictRecord]]:
    """Resolve directive conflicts after composition and before final render."""
    packets = list(composed.packets)
    phenotype_packet = _build_phenotype_packet_from_manifest(composed.manifest)
    if phenotype_packet is not None:
        packets.append(phenotype_packet)

    entries: list[dict[str, Any]] = []
    for packet_index, packet in enumerate(packets):
        for directive_index, directive_text in enumerate(_split_conflict_directives(packet.text)):
            entries.append(
                {
                    "id": f"{packet.layer}:{packet.name}:{directive_index}",
                    "packet_index": packet_index,
                    "packet": packet,
                    "text": directive_text,
                    "hard": packet.constraint_class == "HARD",
                    "priority": (
                        1 if packet.constraint_class == "HARD" else 0,
                        _layer_priority(packet.layer),
                        _specificity_score(packet),
                        -packet_index,
                        -directive_index,
                    ),
                }
            )

    entries.sort(key=lambda entry: entry["priority"], reverse=True)

    kept: list[dict[str, Any]] = []
    conflicts: list[ConflictRecord] = []

    for entry in entries:
        topic, stance = _directive_topic_and_stance(entry["text"])
        if topic is None:
            kept.append(entry)
            continue

        losing = False
        for winner in kept:
            winner_topic, winner_stance = _directive_topic_and_stance(winner["text"])
            if winner_topic == topic and winner_stance != stance:
                conflicts.append(
                    ConflictRecord(
                        topic=topic,
                        winner_layer=winner["packet"].layer,
                        winner_packet=winner["packet"].name,
                        winner_text=winner["text"],
                        loser_layer=entry["packet"].layer,
                        loser_packet=entry["packet"].name,
                        loser_text=entry["text"],
                        reason=(
                            "HARD wins first; otherwise higher layer wins; "
                            "same-layer tie goes to the more specific packet."
                        ),
                    )
                )
                losing = True
                break
        if not losing:
            kept.append(entry)

    kept_ids = {entry["id"] for entry in kept}
    rebuilt_packets: list[DirectivePacket] = []
    for packet_index, packet in enumerate(packets):
        kept_texts = [
            entry["text"]
            for entry in kept
            if entry["packet_index"] == packet_index and entry["id"] in kept_ids
        ]
        if not kept_texts:
            continue
        rebuilt_packets.append(
            DirectivePacket(
                layer=packet.layer,
                name=packet.name,
                text="\n".join(kept_texts),
                constraint_class=packet.constraint_class,
                domain=packet.domain,
                model=packet.model,
                tags=set(packet.tags),
            )
        )

    rendered = _render_directive_text(rebuilt_packets)
    cid = _compute_cid(rebuilt_packets, composed.manifest["model"])
    token_estimate = max(len(rendered) // 4, 1)
    density = composed.constraint_count / token_estimate

    manifest = dict(composed.manifest)
    manifest["cid"] = cid
    manifest["resolved_conflicts"] = [
        {
            "topic": conflict.topic,
            "winner_layer": conflict.winner_layer,
            "winner_packet": conflict.winner_packet,
            "loser_layer": conflict.loser_layer,
            "loser_packet": conflict.loser_packet,
        }
        for conflict in conflicts
    ]

    resolved = ComposedDirectiveSet(
        packets=rebuilt_packets,
        rendered_text=rendered,
        policy=composed.policy,
        cid=cid,
        constraint_count=composed.constraint_count,
        token_estimate=token_estimate,
        constraint_density=density,
        coherence_budget=composed.coherence_budget,
        pruned_soft=list(composed.pruned_soft),
        manifest=manifest,
    )
    return resolved, conflicts
