        except (OSError, json.JSONDecodeError):
            continue
        if isinstance(payload, list):
            entries.extend(item for item in payload if isinstance(item, dict))
        elif isinstance(payload, dict):
            entries.append(payload)
    return entries


def _estimate_constraint_count_from_prompt(prompt_text: str) -> int:
    import re

    count = 0
    for line in prompt_text.splitlines():
        stripped = line.strip()
        if re.match(r"^(\d+[.)]|[-*])\s+", stripped):
            count += 1
        elif "=" in stripped and "." in stripped.split("=", 1)[0]:
            count += 1
    return max(count, 1)


def _extract_density(entry: dict[str, Any]) -> float | None:
    metadata = entry.get("metadata", {})
    manifest = entry.get("manifest", {})

    for candidate in (
        entry.get("constraint_density"),
        metadata.get("constraint_density"),
        manifest.get("constraint_density"),
    ):
        if isinstance(candidate, (int, float)) and candidate > 0:
            return float(candidate)

    chars = (
        entry.get("directive_chars")
        or entry.get("chars")
        or entry.get("prompt_length")
        or metadata.get("directive_chars")
        or metadata.get("chars")
        or manifest.get("directive_chars")
    )
    if not isinstance(chars, (int, float)) or chars <= 0:
        prompt_text = (
            entry.get("system_prompt")
            or metadata.get("system_prompt")
            or entry.get("cdsfl_directives")
            or metadata.get("cdsfl_directives")
            or ""
        )
        if not prompt_text:
            return None
        chars = len(prompt_text)
        constraint_count = _estimate_constraint_count_from_prompt(prompt_text)
        return constraint_count / max(int(chars) // 4, 1)

    constraint_count = (
        entry.get("constraint_count")
        or metadata.get("constraint_count")
        or manifest.get("constraint_count")
    )
    if not isinstance(constraint_count, (int, float)) or constraint_count <= 0:
        prompt_text = (
            entry.get("system_prompt")
            or metadata.get("system_prompt")
            or entry.get("cdsfl_directives")
            or metadata.get("cdsfl_directives")
            or ""
        )
        constraint_count = _estimate_constraint_count_from_prompt(prompt_text) if prompt_text else max(int(chars) // 70, 1)

    return float(constraint_count) / max(int(chars) // 4, 1)


def _extract_response_text(entry: dict[str, Any]) -> str:
    response = entry.get("response", "")
    if isinstance(response, str):
        return response
    if isinstance(response, dict):
        for key in ("text", "content", "response"):
            value = response.get(key)
            if isinstance(value, str):
                return value
    return ""


def _estimate_findings_count(entry: dict[str, Any], response_text: str) -> int:
    import re

    metadata = entry.get("metadata", {})
    for candidate in (
        entry.get("findings_count"),
        metadata.get("findings_count"),
        entry.get("N"),
        metadata.get("N"),
    ):
        if isinstance(candidate, int) and candidate >= 0:
            return candidate

    patterns = [
        r"(?im)^FINDING_ID\s*:",
        r"(?im)^finding_id\s*:",
        r"(?im)^FINDING\b",
        r"(?im)^Issue\s*\d*\s*:",
        r"(?im)^Problem\s*\d*\s*:",
        r"(?im)^Bug\s*\d*\s*:",
    ]
    count = sum(len(re.findall(pattern, response_text)) for pattern in patterns)
    if count > 0:
        return count

    paragraphs = [p for p in response_text.split("\n\n") if len(p.strip()) > 80]
    return len(paragraphs)


def calibrate_coherence_thresholds(
    log_root: str | Path,
    *,
    quality_drop_fraction: float = 0.10,
    min_points_per_model: int = 5,
) -> dict[str, float]:
    """Calibrate per-model coherence thresholds from experiment logs."""
    model_samples: dict[str, list[tuple[float, float]]] = {}

    for entry in _iter_experiment_entries(log_root):
        model = entry.get("model") or entry.get("model_label")
        if not isinstance(model, str) or not model:
            continue

        density = _extract_density(entry)
        if density is None:
            continue

        response_text = _extract_response_text(entry)
        if not response_text:
            continue

        findings_count = _estimate_findings_count(entry, response_text)
        response_tokens = max(len(response_text) // 4, 1)
        quality = (findings_count / response_tokens) * 1000.0

        model_samples.setdefault(model, []).append((density, quality))

    thresholds: dict[str, float] = {}

    for model, samples in model_samples.items():
        if len(samples) < min_points_per_model:
            continue

        bins: dict[float, list[float]] = {}
        for density, quality in samples:
            bucket = round(density, 4)
            bins.setdefault(bucket, []).append(quality)

        curve = sorted((density, sum(values) / len(values)) for density, values in bins.items())
        peak_density, peak_quality = max(curve, key=lambda pair: pair[1])

        threshold = peak_density
        seen_peak = False
        consecutive_drop_bins = 0

        for density, quality in curve:
            if density < peak_density:
                continue
            if density == peak_density and not seen_peak:
                seen_peak = True
                threshold = density
                continue

            if quality < peak_quality * (1.0 - quality_drop_fraction):
                consecutive_drop_bins += 1
                if consecutive_drop_bins >= 2 or density == curve[-1][0]:
                    break
            else:
                consecutive_drop_bins = 0
                threshold = density

        thresholds[model] = round(threshold, 4)

    for model, fallback in MODEL_COHERENCE_BUDGETS.items():
        thresholds.setdefault(model, fallback)

    return thresholds
